{
  "anomaly_detected": true,
  "confidence": 0.99,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC1", "NAVC1"],
      "pins": ["FCC1.48", "FCC1.73", "NAVC1.31", "NAVC1.47"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC", "I2C3_SDA_NAVC", "UART3_TX_NAVC"],
      "observed": "Both MCUs’ VCAP pins are connected to signal nets: FCC1 pins 48 and 73 to UART3_TX_FCC and UART3_RX_FCC; NAVC1 pin 31 to I2C3_SDA_NAVC and pin 47 to UART3_TX_NAVC. The VCAP pins have no required external capacitors to ground shown.",
      "expected": "VCAP pins should connect only to the specified decoupling capacitors to ground, not to UART or I2C signals. Keep the debug and peripheral signals on their appropriate MCU signal pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC1 pins 48 and 73 are marked VCAP and carry UART3_TX_FCC and UART3_RX_FCC labels; FCC sheet, page 2."
        },
        {
          "source": "schematic",
          "quote": "NAVC1 pins 31 and 47 are marked VCAP_1 and VCAP_2 and carry I2C3_SDA_NAVC and UART3_TX_NAVC labels; NAVC sheet, page 3."
        },
        {
          "source": "spec",
          "quote": "FCC is populated with an STM32H753VITx and NAVC with an STM32F405RGTx; §1."
        },
        {
          "source": "spec",
          "quote": "UART3 -> Debug (via USB); NAVC sheet, page 3."
        }
      ],
      "impact": "The MCU core-regulator outputs are misused as signal nets, while UART/I2C signals are not correctly connected to those VCAP pins. This can prevent reliable MCU operation, break the affected interfaces, and risk electrical contention.",
      "confidence": 0.99
    }
  ],
  "summary": "An anomaly is present: the VCAP pins on both MCUs are connected to UART/I2C signal nets rather than their required decoupling capacitors. This compromises the MCU core supply connections and the associated interfaces."
}

